#!/usr/bin/env Rscript

# Title: Figure 2 - Immune PCA, cancer groups and chemotherapy associations
# Inputs:
#   - data/pca_inputs.rds and association_results.rds
#     generated by notebooks/15_PCA_imputation_associations.ipynb
#   - Color and theme helpers used by Figure 1 and Figure 4
# Outputs:
#   - plots/Fig2A-F.pdf, .png and .svg
#   - plots/Figure2.pdf (six pages at native panel sizes) and overview PDF/PNG/SVG
#   - Overview: A above B at left, C at right; D-F across the next row
#   - Panels A/B: 6 x 4.8 inches each; panel C: 12 x 9.6 inches
#   - Numeric plotting source data in tables/figure2/
# Usage:
#   Rscript R/Figure2.R
# Use the bundled notebook-15 outputs, or rerun notebook 15 to rebuild them.
# Run this script from the repository root.
# PCA, imputation and tests are read from the notebook outputs; plots are rebuilt.

# --- Setup --------------------------------------------------------------------

suppressPackageStartupMessages({
  library(readr)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(ggrepel)
  library(cowplot)
  library(patchwork)
})

source(file.path(getwd(), "R/functions", "color_schemes.R"))
source(file.path(getwd(), "R/functions", "ggplot2_theme.R"))
source(file.path(getwd(), "R/functions", "pca_figure_io.R"))
source(file.path(getwd(), "R/functions", "figure2_plotting.R"))

project_root <- getwd()
plots_dir <- file.path(project_root, "plots")
tables_dir <- file.path(project_root, "tables", "figure2")
dir.create(plots_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(tables_dir, recursive = TRUE, showWarnings = FALSE)

# --- Read the numerical outputs generated by notebook 15 ----------------------

prepared <- read_pca_figure_outputs(project_root)
inputs <- prepared$inputs
statistics <- prepared$statistics

# --- Construct the six panels -------------------------------------------------

figure2 <- build_figure2_panels(inputs, statistics)
write_figure2_source_tables(figure2, tables_dir)

# --- Export -------------------------------------------------------------------

export_figure2(figure2, plots_dir)
capture.output(sessionInfo(), file = file.path(tables_dir, "sessionInfo.txt"))
message("Figure 2 saved in ", plots_dir)
